from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + skill[i]

        start = 0
        for j in range(len(mana) - 1):
            current_mana = mana[j]
            next_mana = mana[j + 1]

            delay = 0
            for i in range(n):
                required = prefix[i + 1] * current_mana - prefix[i] * next_mana
                if required > delay:
                    delay = required

            start += delay

        return start + prefix[n] * mana[-1]
